(function() {
    'use strict';

    class EthicalCrossroadsAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Ethical Crossroads';
            this.version = '1.1.0';

            this.SCENARIOS = [
                {
                    en: {
                        title: 'Scenario 1: The Permit',
                        narrative: 'Six weeks into your role as country manager, a critical operating permit — needed to maintain $4M/month in revenue — is pending approval with the municipal government. Your government relations manager, a 20-year company veteran, mentions the process can be accelerated for a $25,000 facilitation payment to a mid-level official. The headquarters CFO is pressuring you to meet Q3 targets. The FCPA and OECD Anti-Bribery Convention apply to your operations.',
                        options: [
                            'A) Authorize the facilitation payment. This is standard local practice and the business depends on it.',
                            'B) Refuse the payment. Escalate to headquarters legal/compliance and accept the Q3 revenue miss.',
                            'C) Request a meeting directly with the senior official to understand legitimate process steps without offering payment.',
                            'D) Ask the local government relations manager to handle it however he sees fit, without explicit authorization.'
                        ]
                    },
                    es: {
                        title: 'Escenario 1: El Permiso',
                        narrative: 'A seis semanas de asumir como gerente de pais, un permiso operativo critico — necesario para mantener $4M/mes en ingresos — esta pendiente de aprobacion con el gobierno municipal. Tu gerente de relaciones gubernamentales, un veterano de 20 anos, menciona que el proceso puede acelerarse con un pago de facilitacion de $25,000 a un funcionario. El CFO de la casa matriz presiona por cumplir los objetivos del Q3. La FCPA y la Convencion Anti-Soborno de la OCDE aplican a tus operaciones.',
                        options: [
                            'A) Autorizar el pago de facilitacion. Es practica local estandar y el negocio depende de ello.',
                            'B) Rechazar el pago. Escalar a legal/cumplimiento de la casa matriz y aceptar la perdida de ingresos del Q3.',
                            'C) Solicitar una reunion directa con el funcionario senior para entender los pasos legitimos del proceso sin ofrecer pago.',
                            'D) Pedir al gerente local de relaciones gubernamentales que lo maneje como considere apropiado, sin autorizacion explicita.'
                        ]
                    },
                    scores: {
                        A: { coherence: -5, awareness: -10, reputation: -15 },
                        B: { coherence: 15, awareness: 10, reputation: 12 },
                        C: { coherence: 12, awareness: 12, reputation: 10 },
                        D: { coherence: -10, awareness: -15, reputation: -20 }
                    }
                },
                {
                    en: {
                        title: 'Scenario 2: The River',
                        narrative: 'You receive a confidential report from the plant operations manager: an industrial discharge monitoring system has been malfunctioning for three months. Preliminary internal tests suggest the plant may be exceeding effluent limits for heavy metals. Fixing the system requires a 10-day plant shutdown costing approximately $800,000 in lost production. The plant manager suggests continuing operations while investigating further, since there is no certainty of violation. The plant is located near a river community of approximately 3,000 people.',
                        options: [
                            'A) Halt operations immediately. Notify regulators and begin remediation.',
                            'B) Continue operations for 30 days while commissioning an independent environmental audit.',
                            'C) Conduct an internal investigation for 2 weeks before deciding whether regulatory notification is required.',
                            'D) Fix the monitoring equipment without production shutdown. Rely on the fixed equipment going forward.'
                        ]
                    },
                    es: {
                        title: 'Escenario 2: El Rio',
                        narrative: 'Recibes un informe confidencial del gerente de operaciones de planta: un sistema de monitoreo de descargas industriales ha estado fallando por tres meses. Pruebas internas preliminares sugieren que la planta podria estar excediendo los limites de efluentes para metales pesados. Reparar el sistema requiere un cierre de planta de 10 dias con un costo aproximado de $800,000 en produccion perdida. El gerente de planta sugiere continuar operaciones mientras se investiga, ya que no hay certeza de violacion. La planta esta ubicada cerca de una comunidad fluvial de aproximadamente 3,000 personas.',
                        options: [
                            'A) Detener operaciones inmediatamente. Notificar a los reguladores y comenzar la remediacion.',
                            'B) Continuar operaciones por 30 dias mientras se comisiona una auditoria ambiental independiente.',
                            'C) Realizar una investigacion interna por 2 semanas antes de decidir si se requiere notificacion al regulador.',
                            'D) Reparar el equipo de monitoreo sin cierre de produccion. Confiar en el equipo reparado en adelante.'
                        ]
                    },
                    scores: {
                        A: { coherence: 15, awareness: 15, reputation: 15 },
                        B: { coherence: -5, awareness: -8, reputation: -10 },
                        C: { coherence: -3, awareness: -5, reputation: -5 },
                        D: { coherence: -8, awareness: -12, reputation: -8 }
                    }
                },
                {
                    en: {
                        title: 'Scenario 3: The Whistleblower',
                        narrative: 'An anonymous email arrives at your personal company inbox: an employee in the procurement department alleges that the purchasing director is receiving kickbacks from three suppliers, inflating prices by an estimated 15-20%. The email includes partial evidence — screenshots of personal bank transfers. The purchasing director is your most effective operational manager, responsible for the supply chain that supported last quarter record performance. Headquarters has not been informed.',
                        options: [
                            'A) Forward the email to Group Legal and initiate a formal investigation through proper channels, notifying the board audit committee.',
                            'B) Confront the purchasing director directly with the allegations and give them 48 hours to explain.',
                            'C) Retain an external forensic firm for a discreet investigation before deciding on escalation.',
                            'D) Conclude that anonymous tips without verified evidence do not warrant action. File the email without response.'
                        ]
                    },
                    es: {
                        title: 'Escenario 3: El Denunciante',
                        narrative: 'Un correo anonimo llega a tu buzon corporativo personal: un empleado del departamento de compras alega que el director de compras esta recibiendo comisiones ilicitas de tres proveedores, inflando precios entre un 15-20% estimado. El correo incluye evidencia parcial — capturas de transferencias bancarias personales. El director de compras es tu gerente operativo mas efectivo, responsable de la cadena de suministro que sustento el rendimiento record del trimestre pasado. La casa matriz no ha sido informada.',
                        options: [
                            'A) Reenviar el correo a Legal Corporativo e iniciar una investigacion formal por los canales apropiados, notificando al comite de auditoria del directorio.',
                            'B) Confrontar al director de compras directamente con las acusaciones y darle 48 horas para explicarse.',
                            'C) Contratar una firma forense externa para una investigacion discreta antes de decidir sobre la escalacion.',
                            'D) Concluir que denuncias anonimas sin evidencia verificada no ameritan accion. Archivar el correo sin respuesta.'
                        ]
                    },
                    scores: {
                        A: { coherence: 15, awareness: 12, reputation: 12 },
                        B: { coherence: 5, awareness: -5, reputation: -8 },
                        C: { coherence: 12, awareness: 10, reputation: 10 },
                        D: { coherence: -10, awareness: -15, reputation: -15 }
                    }
                },
                {
                    en: {
                        title: 'Scenario 4: The Database',
                        narrative: 'The marketing director presents a growth initiative: a third-party data broker offers to sell a database of 800,000 regional consumers containing behavioral, health-related, and financial data scraped from multiple sources. The marketing director assures you the transaction is legal — the broker has terms of service covering data usage. Revenue potential: $2.3M in the first year from targeted cross-selling campaigns. Your operations fall under LGPD (Brazil data protection law), analogous to GDPR.',
                        options: [
                            'A) Approve the data purchase. Legal review has cleared it and the revenue potential is significant.',
                            'B) Request a full data provenance audit from the vendor before approving — demand evidence of genuine individual consent.',
                            'C) Reject the database. Commission your own opt-in data collection program, which will take 18 months but produce ethically clean data.',
                            'D) Approve the database use for a 90-day pilot while the legal team develops a longer-term data governance policy.'
                        ]
                    },
                    es: {
                        title: 'Escenario 4: La Base de Datos',
                        narrative: 'La directora de marketing presenta una iniciativa de crecimiento: un intermediario de datos ofrece vender una base de datos de 800,000 consumidores regionales con datos conductuales, de salud y financieros recopilados de multiples fuentes. La directora de marketing asegura que la transaccion es legal — el intermediario tiene terminos de servicio que cubren el uso de datos. Potencial de ingresos: $2.3M en el primer ano por campanas de venta cruzada. Tus operaciones caen bajo la LGPD (ley de proteccion de datos de Brasil), analoga al GDPR.',
                        options: [
                            'A) Aprobar la compra de datos. La revision legal la autorizo y el potencial de ingresos es significativo.',
                            'B) Solicitar una auditoria completa de procedencia de datos al proveedor — exigir evidencia de consentimiento individual genuino.',
                            'C) Rechazar la base de datos. Comisionar un programa propio de recoleccion de datos con consentimiento, que tomara 18 meses pero producira datos eticamente limpios.',
                            'D) Aprobar el uso de la base de datos para un piloto de 90 dias mientras el equipo legal desarrolla una politica de gobernanza de datos a largo plazo.'
                        ]
                    },
                    scores: {
                        A: { coherence: -8, awareness: -12, reputation: -10 },
                        B: { coherence: 12, awareness: 15, reputation: 10 },
                        C: { coherence: 15, awareness: 12, reputation: 15 },
                        D: { coherence: -6, awareness: -10, reputation: -8 }
                    }
                },
                {
                    en: {
                        title: 'Scenario 5: The Community',
                        narrative: 'Your factory has been the economic anchor of a mid-size city for 22 years, employing 340 people directly and supporting an estimated 1,200 additional jobs locally. Headquarters has decided to relocate manufacturing to Vietnam to reduce costs by 34%, effective in 14 months. You are instructed to manage the transition communications. The city unemployment rate will rise from 6% to an estimated 18% after the closure. The mayor and local governor are requesting a meeting.',
                        options: [
                            'A) Execute the headquarters plan with full legal compliance — provide required severance, outplacement services, and advance notice.',
                            'B) Negotiate with headquarters for a transition support fund (retraining, local supplier development, community infrastructure) beyond legal requirements.',
                            'C) Propose to headquarters a hybrid model: partial relocation phased over 36 months, preserving 120 jobs in higher-skill roles.',
                            'D) Be transparent with the mayor and governor immediately, before the official announcement, to allow maximum community preparation time.'
                        ]
                    },
                    es: {
                        title: 'Escenario 5: La Comunidad',
                        narrative: 'Tu fabrica ha sido el ancla economica de una ciudad mediana por 22 anos, empleando a 340 personas directamente y sosteniendo aproximadamente 1,200 empleos adicionales localmente. La casa matriz ha decidido relocalizar la manufactura a Vietnam para reducir costos en 34%, efectivo en 14 meses. Se te instruye manejar las comunicaciones de transicion. La tasa de desempleo de la ciudad subira de 6% a un estimado de 18% tras el cierre. El alcalde y el gobernador solicitan una reunion.',
                        options: [
                            'A) Ejecutar el plan de la casa matriz con pleno cumplimiento legal — proveer indemnizacion requerida, servicios de recolocacion y aviso previo.',
                            'B) Negociar con la casa matriz un fondo de apoyo a la transicion (capacitacion, desarrollo de proveedores locales, infraestructura comunitaria) mas alla de los requisitos legales.',
                            'C) Proponer a la casa matriz un modelo hibrido: relocalizacion parcial en fases de 36 meses, preservando 120 empleos en roles de mayor cualificacion.',
                            'D) Ser transparente con el alcalde y gobernador inmediatamente, antes del anuncio oficial, para permitir el maximo tiempo de preparacion comunitaria.'
                        ]
                    },
                    scores: {
                        A: { coherence: 5, awareness: -10, reputation: -8 },
                        B: { coherence: 12, awareness: 15, reputation: 15 },
                        C: { coherence: 10, awareness: 12, reputation: 12 },
                        D: { coherence: 8, awareness: 10, reputation: 5 }
                    }
                },
                {
                    en: {
                        title: 'Scenario 6: The Board',
                        narrative: 'You are invited to present at a board audit committee meeting. Over the previous five scenarios, your decisions have generated a confidential ethics portfolio — a documented record of every judgment call and its organizational consequence. The board has received an anonymous report alleging improper conduct across environmental, procurement, and data practices. The board chair asks you directly: Give me your honest assessment of this operation ethical health.',
                        options: [
                            'A) Give a fully transparent briefing, including disclosure of all decisions made, their rationale, and unresolved ethical risks.',
                            'B) Present a curated summary that emphasizes positive decisions and frames unresolved issues as work in progress.',
                            'C) Recommend commissioning an independent ethics audit to provide the board with an objective view.',
                            'D) Refer the board to the legal and compliance department. Frame ethical questions as matters of regulatory adherence.'
                        ]
                    },
                    es: {
                        title: 'Escenario 6: El Directorio',
                        narrative: 'Has sido invitado a presentar ante el comite de auditoria del directorio. A lo largo de los cinco escenarios anteriores, tus decisiones han generado un portafolio etico confidencial — un registro documentado de cada juicio realizado y su consecuencia organizacional. El directorio ha recibido un informe anonimo alegando conducta impropia en practicas ambientales, de compras y de datos. El presidente del directorio te pregunta directamente: Dame tu evaluacion honesta de la salud etica de esta operacion.',
                        options: [
                            'A) Dar un informe totalmente transparente, incluyendo la divulgacion de todas las decisiones tomadas, su justificacion y los riesgos eticos no resueltos.',
                            'B) Presentar un resumen curado que enfatice las decisiones positivas y enmarque los temas no resueltos como trabajo en progreso.',
                            'C) Recomendar comisionar una auditoria etica independiente para proveer al directorio con una vision objetiva.',
                            'D) Referir al directorio al departamento legal y de cumplimiento. Enmarcar las preguntas eticas como asuntos de adherencia regulatoria.'
                        ]
                    },
                    scores: {
                        A: { coherence: 15, awareness: 15, reputation: 18 },
                        B: { coherence: -10, awareness: -8, reputation: -15 },
                        C: { coherence: 8, awareness: 10, reputation: 8 },
                        D: { coherence: -5, awareness: -10, reputation: -5 }
                    }
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    coherence: 50,
                    awareness: 50,
                    reputation: 50,
                    coherenceHistory: [],
                    awarenessHistory: [],
                    reputationHistory: [],
                    priorChoices: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    choice: 'A'
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            this._updateBriefing(window.mySimulation.state);
            var selected = document.querySelector('input[name="ethicsChoice"]:checked');
            if (!selected) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('no_selection_warning'), 'warning'
                );
                return false;
            }
            decisions.choice = selected.value;
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var idx = Math.min((state.currentPeriod || 1) - 1, this.SCENARIOS.length - 1);
            var scenario = this.SCENARIOS[idx];
            var scoreDeltas = scenario.scores[d.choice] || { coherence: 0, awareness: 0, reputation: 0 };

            var coherenceDelta = scoreDeltas.coherence;
            var awarenessDelta = scoreDeltas.awareness;
            var reputationDelta = scoreDeltas.reputation;

            var priorChoices = state.domainState.priorChoices || [];

            if (idx === 4 && priorChoices.length >= 2 && priorChoices[1] === 'A') {
                reputationDelta += 5;
            }

            if (idx === 5) {
                if (priorChoices.length >= 1 && (priorChoices[0] === 'A' || priorChoices[0] === 'D')) {
                    reputationDelta -= 8;
                }
                if (priorChoices.length >= 2 && (priorChoices[1] === 'B' || priorChoices[1] === 'C')) {
                    reputationDelta -= 5;
                }
                if (d.choice === 'A') {
                    var goodDecisions = 0;
                    for (var p = 0; p < priorChoices.length; p++) {
                        var pc = priorChoices[p];
                        var sc = this.SCENARIOS[p].scores[pc];
                        if (sc && (sc.coherence + sc.awareness + sc.reputation) > 20) {
                            goodDecisions++;
                        }
                    }
                    if (goodDecisions >= 3) {
                        reputationDelta += 5;
                        coherenceDelta += 3;
                    }
                }
                if (d.choice === 'B') {
                    var badDecisions = 0;
                    for (var q = 0; q < priorChoices.length; q++) {
                        var qc = priorChoices[q];
                        var qs = this.SCENARIOS[q].scores[qc];
                        if (qs && (qs.coherence + qs.awareness + qs.reputation) < 0) {
                            badDecisions++;
                        }
                    }
                    if (badDecisions >= 2) {
                        reputationDelta -= 10;
                    }
                }
            }

            state.domainState.coherence = Math.max(0, Math.min(100, state.domainState.coherence + coherenceDelta));
            state.domainState.awareness = Math.max(0, Math.min(100, state.domainState.awareness + awarenessDelta));
            state.domainState.reputation = Math.max(0, Math.min(100, state.domainState.reputation + reputationDelta));

            state.domainState.coherenceHistory.push(state.domainState.coherence);
            state.domainState.awarenessHistory.push(state.domainState.awareness);
            state.domainState.reputationHistory.push(state.domainState.reputation);
            state.domainState.priorChoices.push(d.choice);

            var lang = this._getLang();
            var scenarioTitle = scenario[lang] ? scenario[lang].title : scenario.en.title;

            var radios = document.querySelectorAll('input[name="ethicsChoice"]');
            for (var r = 0; r < radios.length; r++) {
                radios[r].checked = false;
            }

            // Show the NEXT scenario synchronously. state.currentPeriod is still the
            // scenario we just scored (the framework increments it *after* this method
            // returns), so the next scenario is currentPeriod + 1. The prior 500ms timer
            // fired *after* that increment, so it read currentPeriod+1 and added 1 again —
            // displaying scenario N+2 and skipping N+1, while calculateResults kept scoring
            // by the counter, applying each choice to the wrong dilemma.
            this._updateBriefing({ currentPeriod: state.currentPeriod + 1, domainState: state.domainState });

            return {
                period: state.currentPeriod,
                scenarioTitle: scenarioTitle,
                choice: d.choice,
                coherenceDelta: coherenceDelta,
                awarenessDelta: awarenessDelta,
                reputationDelta: reputationDelta,
                coherence: state.domainState.coherence,
                awareness: state.domainState.awareness,
                reputation: state.domainState.reputation
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('coherenceDisplay', 'domainState.coherence', function(v) { return Math.round(v) + '/100'; });
            uiManager.bind('awarenessDisplay', 'domainState.awareness', function(v) { return Math.round(v) + '/100'; });
            uiManager.bind('reputationDisplay', 'domainState.reputation', function(v) { return Math.round(v) + '/100'; });
        }

        getChartConfig() {
            return {
                scoresChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Ethical Coherence',
                                data: [],
                                borderColor: '#3182ce',
                                backgroundColor: 'rgba(49,130,206,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.3
                            },
                            {
                                label: 'Stakeholder Awareness',
                                data: [],
                                borderColor: '#38a169',
                                backgroundColor: 'rgba(56,161,105,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.3
                            },
                            {
                                label: 'Leadership Reputation',
                                data: [],
                                borderColor: '#d69e2e',
                                backgroundColor: 'rgba(214,158,46,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.3
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Score Evolution' }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 100, title: { display: true, text: 'Score' } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.coherenceHistory.map(function(_, i) { return 'S' + (i + 1); });
            return {
                scoresChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.coherenceHistory },
                        { data: state.domainState.awarenessHistory },
                        { data: state.domainState.reputationHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};

            var lastRecord = history[history.length - 1];
            var finalCoherence = lastRecord.results ? lastRecord.results.coherence : 50;
            var finalAwareness = lastRecord.results ? lastRecord.results.awareness : 50;
            var finalReputation = lastRecord.results ? lastRecord.results.reputation : 50;
            var composite = Math.round((finalCoherence + finalAwareness + finalReputation) / 3);

            var performance = 'Developing';
            if (composite >= 75) performance = 'Exemplary';
            else if (composite >= 60) performance = 'Proficient';
            else if (composite >= 45) performance = 'Developing';
            else performance = 'At Risk';

            var insights = [];
            if (finalCoherence >= 70) {
                insights.push('Strong ethical framework consistency across scenarios.');
            } else {
                insights.push('Ethical reasoning varied significantly across scenarios — consider adopting a more consistent framework.');
            }
            if (finalAwareness >= 70) {
                insights.push('Excellent stakeholder awareness — broad consideration of affected parties.');
            } else {
                insights.push('Stakeholder analysis could be broader — some affected groups were overlooked.');
            }
            if (finalReputation >= 70) {
                insights.push('Decisions built strong organizational trust and leadership credibility.');
            } else {
                insights.push('Some decisions eroded organizational trust — review the cascading reputational effects.');
            }

            return {
                compositeScore: composite,
                ethicalCoherence: finalCoherence,
                stakeholderAwareness: finalAwareness,
                leadershipReputation: finalReputation,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var total = (results.coherenceDelta || 0) + (results.awarenessDelta || 0) + (results.reputationDelta || 0);
            if (total < -20) return window.mySimulation.t('hint_very_negative');
            if (total < 0) return window.mySimulation.t('hint_negative');
            if (total > 30) return window.mySimulation.t('hint_very_positive');
            if (total > 10) return window.mySimulation.t('hint_positive');
            return window.mySimulation.t('hint_neutral');
        }

